def coconut():
    flower = G(''.join(G(P('M0 0 Q-16 -8 -11 -28 Q2 -22 0 0Z', '#ee4a70', 2.6), i * 72, 0, 0) for i in range(5)) + C(0, 0, 6, '#ffd23f', 2.4), 0, 54, 190, 1)
    a = (C(128, 140, 72, '#4f9a3c') + P('M62 124 Q70 78 128 70 Q186 78 194 124 Q180 96 128 92 Q76 96 62 124Z', '#7cc24a', 0) + HL('M80 110 Q92 84 124 78', .45, 6) +
         ''.join(S(p, '#3a7a2c', 3, .7) for p in ['M70 150 Q128 176 186 150', 'M82 176 Q128 196 176 176']) + E(128, 92, 24, 10, '#f3e6c0', 3) + E(128, 92, 16, 6, '#5a3a1a', 2.4) +
         straw(144, 30, 130, 100, '#ffd23f') + S('M178 90 L196 40', '#8a5a2a', 3.5) + P('M170 42 Q196 22 222 46 Q196 56 170 42Z', '#e5453a') + S('M184 36 L184 50 M196 32 L196 52 M208 36 L206 50', '#fff', 2, .8) +
         flower + P('M196 180 q22 -10 34 8 q-20 14 -34 -8Z', '#4c8a2c') + P('M170 206 q18 -14 36 -2 q-16 16 -36 2Z', '#59a83a'))
    return build(circle_d(128, 128, 104), ('#9eecf4', '#3fb6cc'), a, star(52, 56, 9) + star(208, 208, 8), 6)


def tea_glass():
    ist = (P('M96 66 H160 Q164 98 150 120 Q142 134 152 160 Q158 188 160 198 H96 Q98 188 104 160 Q114 134 106 120 Q92 98 96 66Z', GLASS, 3.4, INK, .86) +
           P('M99 84 H157 Q158 98 150 116 Q142 132 150 156 Q156 184 158 196 H98 Q100 184 106 156 Q114 132 106 116 Q98 98 99 84Z', '#c8641a') + P('M99 84 H157 Q158 98 150 116 Q142 132 150 156 Q156 184 158 196 H98 Q100 184 106 156 Q114 132 106 116 Q98 98 99 84Z', 'none', 0.1) +
           E(128, 84, 29, 5, '#e68a2a', 2) + HL('M104 76 Q108 110 112 130', .55, 4) + HL('M108 168 Q106 184 106 194', .4, 3.5) + S('M96 66 H160', '#e8c36a', 4))
    sauc = E(128, 206, 76, 16, '#f0d38a', 3.4) + E(128, 202, 58, 10, '#fff2c2', 2.4) + S('M62 206 Q128 226 194 206', '#c99a3a', 2.4, .8)
    a = (sauc + ist + R(176, 196, 18, 18, 3, '#fff', 2.6, 12) + steam(118, 56, 44) + steam(144, 52, 40) +
         ''.join(E(x, y, 6, 3.4, '#8cc063', 2, r, '#4a7a2a') for x, y, r in [(62, 192, 20), (78, 214, -14)]))
    return build(arch_d(128, 18, 200, 240), ('#ffe2a8', '#f2a548'), a, star(208, 50, 9, '#fff') + star(46, 196, 8, '#fff'), -5)


def teapot():
    a = (P('M62 150 Q62 96 128 96 Q194 96 194 150 Q194 206 128 210 Q62 206 62 150Z', '#2f8a86') + HL('M76 138 Q82 112 112 104', .4, 5) + S('M64 150 Q128 166 192 150', '#e8c36a', 4) + S('M70 182 Q128 198 186 182', '#e8c36a', 3, .8) +
         P('M92 96 Q92 80 128 80 Q164 80 164 96Z', '#256f6c') + C(128, 72, 9, '#e8c36a') + P('M190 140 Q232 130 226 90 Q214 116 192 118Z', '#2f8a86') + P('M64 120 Q28 110 32 156 Q38 188 66 176', 'none', 9) + P('M64 120 Q28 110 32 156 Q38 188 66 176', 'none', 5, '#2f8a86') +
         E(128, 224, 60, 10, '#5a3a22') + R(78, 208, 100, 14, 6, '#8a5a2a') + steam(120, 66, 40) +
         G(P('M-14 -4 H14 L10 26 Q0 30 -10 26Z', GLASS, 3, INK, .9) + P('M-12 6 H12 L9 24 Q0 28 -9 24Z', '#c8641a'), 0, 52, 222, 1) + G(P('M-14 -4 H14 L10 26 Q0 30 -10 26Z', GLASS, 3, INK, .9) + P('M-12 6 H12 L9 24 Q0 28 -9 24Z', '#c8641a'), 0, 204, 222, 1))
    return build(blob_d(128, 128, 104, 100, 9, .05), ('#ffd49a', '#e88a4a'), a, star(210, 54, 9) + star(44, 60, 8), 4)


def arabic_coffee():
    dallah = (P('M100 62 Q100 44 128 44 Q156 44 156 62 L150 82 Q172 96 176 140 L184 212 Q184 224 172 224 H84 Q72 224 72 212 L80 140 Q84 96 106 82Z', '#d9a02e') +
              P('M106 82 Q84 96 80 140 L72 212 Q72 224 84 224 H96 Q92 190 100 140 Q104 100 120 86Z', '#b87d1a') + HL('M110 100 Q96 130 94 176', .5, 4.5) +
              S('M76 150 H180 M74 186 H182', '#7a4a10', 3, .6) + P('M150 90 Q196 80 214 52 L206 46 Q186 72 148 76Z', '#d9a02e') + C(210, 49, 6, '#b87d1a', 3) +
              P('M80 100 Q44 100 44 140 Q44 176 78 176 Q58 160 62 140 Q64 118 90 112Z', '#b87d1a') + C(128, 40, 8, '#7a4a10', 3) + steam(180, 36, 30))
    cup = G(P('M-18 -4 H18 Q18 22 0 24 Q-18 22 -18 -4Z', '#fff6e2') + E(0, -4, 18, 5, '#5a2e12', 2.4) + S('M-12 4 H12', '#e5453a', 2.4), 0, 206, 196, 1)
    dates = ''.join(E(x, y, 12, 7, '#6b2f1c', 3, r) + HL('M%s %s h8' % (x - 5, y - 2), .3, 2.2) for x, y, r in [(46, 224, -20), (66, 232, 10)])
    return build(shield_d(128, 20, 204, 218), ('#d8c8f0', '#8a6cc4'), dallah + cup + dates + dots([(32, 190), (52, 200)], 5, '#4c8a2c'), star(206, 44, 9) + star(44, 64, 8), 4)


def espresso():
    art = (E(128, 118, 52, 38, '#fff6e2', 3.4) + E(128, 118, 40, 26, '#7a3f1e', 2.6) + E(128, 118, 28, 18, '#d4a066') +
           P('M128 104 Q138 112 128 132 Q118 112 128 104Z', '#7a3f1e', 0) + S('M128 106 Q142 116 128 132 M128 106 Q114 116 128 132 M128 112 V128', '#7a3f1e', 2.6, .9))
    a = (E(128, 190, 92, 24, '#f6e8d0', 3.4) + E(128, 186, 70, 16, '#fff6e2', 2.4) +
         P('M58 112 H198 Q198 188 128 192 Q58 188 58 112Z', '#e0794a') + E(128, 112, 70, 20, '#fff6e2', 3.4) + E(128, 112, 56, 14, '#6a3414', 2.6) + E(128, 112, 40, 9, '#e8c490') +
         S('M128 104 Q146 112 128 122 Q110 112 128 104 M128 106 V120', '#6a3414', 2.4, .9) + HL('M70 130 Q74 170 100 182', .45, 5) +
         P('M196 126 Q232 120 226 154 Q218 182 190 176', 'none', 9) + P('M196 126 Q232 120 226 154 Q218 182 190 176', 'none', 5, '#e0794a') +
         ''.join(G(E(0, 0, 8, 5, '#5a2e12', 2.4) + S('M-6 0 q6 -3 12 0', '#a8683c', 1.6), r, x, y) for x, y, r in [(44, 206, 20), (214, 208, -30), (60, 226, -10)]) + steam(112, 74, 40) + steam(140, 70, 36))
    return build(circle_d(128, 128, 104), ('#e3cdb2', '#b98a5c'), a, star(206, 50, 9, '#fff') + star(46, 62, 8, '#fff'), -5)


def hot_choc():
    marsh = ''.join(R(x, y, 22, 20, 7, '#fff6f4', 3, r) for x, y, r in [(92, 82, -12), (124, 74, 8), (150, 88, 18), (112, 100, 0)])
    a = (P('M62 90 H182 Q184 186 124 200 Q64 186 62 90Z', '#c9322e') + HL('M72 100 Q76 160 100 186', .4, 5) + S('M64 128 H180', '#fff', 3.4, .85) + S('M68 156 H174', '#fff', 3, .6) +
         E(122, 90, 60, 14, '#4a2412', 3.4) + E(122, 90, 48, 9, '#7a3f1e') + marsh +
         P('M182 108 Q226 100 220 142 Q212 172 178 164', 'none', 9) + P('M182 108 Q226 100 220 142 Q212 172 178 164', 'none', 5, '#c9322e') +
         R(150, 40, 10, 62, 4, '#a8603a', 3, 24) + S('M150 62 l12 6 M156 78 l12 6', '#7a3c1e', 2, .8) + steam(94, 56, 40) + steam(124, 52, 38) )
    a += NE(124, 214, 78, 12, '#3a1a0c', 0, .25)
    return build(rrect_d(26, 26, 204, 204, 66), ('#ffb0a0', '#e0605a'), a, star(206, 52, 9, '#fff') + star(46, 204, 8, '#fff'), 5)


